 diffs=function(a,b){if(!ConnectedV2.is(a)&&!ConnectedV2.is(b))return diffLegacy(a,b);const rows=[],labels=Object.fromEntries(ConnectedCore.multi.FIELDS.map(([k,n])=>[k,n])),add=(n,x,y)=>{if(String(x)!==String(y))rows.push(n+'：'+(x??'未填')+' → '+(y??'未填'));};for(const side of ['player','enemy'])for(const k of new Set([...Object.keys(side==='player'?a.player:a.world.enemy),...Object.keys(side==='player'?b.player:b.world.enemy)]))add((side==='player'?'角色':'敌人')+(labels[k]||k),(side==='player'?a.player:a.world.enemy)[k],(side==='player'?b.player:b.world.enemy)[k]);for(const k of ConnectedCore.multi.TYPES)add(ConnectedCore.multi.NAMES[k]+'启用',a.types?.[k],b.types?.[k]);for(const k of Object.keys(a.mechanisms||{}))add(k+'机制启用',a.mechanisms[k],b.mechanisms?.[k]);for(const u of b.upgrades){const x=a.upgrades.find(v=>v.id===u.id);if(!x){rows.push('新增'+u.name+'升级');continue;}for(const k of ['enabled','increment','costBase','costStep','maxLevel'])add((u.name||u.id)+k,x[k],u[k]);}add('升级价格倍率',a.economy.costScale,b.economy.costScale);add('总关数',a.world.stageCount,b.world.stageCount);for(const k of new Set([...Object.keys(a.world.steps||{}),...Object.keys(b.world.steps||{})]))add('每关增加'+(labels[k]||k),a.world.steps?.[k],b.world.steps?.[k]);for(const k of ['rewardBase','rewardStep'])add(k,a.world[k],b.world[k]);for(const k of ['initialCoins','incomePerSecond','incomeDuringCombat'])add(k,a.economy[k],b.economy[k]);add('上线时间（小时）',a.behavior.visitHours.join('、'),b.behavior.visitHours.join('、'));add('每次在线分钟',a.behavior.sessionMinutes,b.behavior.sessionMinutes);add('离线收益上限',a.behavior.offlineCapHours,b.behavior.offlineCapHours);add('购买顺序',a.strategy.order.map(k=>upgradeNames[k]).join('、'),b.strategy.order.map(k=>upgradeNames[k]).join('、'));return rows;};
