  const labels={critical:'暴击',armor:'护甲',block:'格挡',leech:'吸血',regen:'回复',bonuses:'伤害增强',resistance:'抗性',enabled:'启用',increment:'每级增加',costBase:'首级实际价格',costStep:'每级实际加价',maxLevel:'等级上限',rewardBase:'首关奖励',rewardStep:'每关增加奖励',initialCoins:'初始金币',incomePerSecond:'每秒固定金币',incomeDuringCombat:'战斗中收金币',...Object.fromEntries(ConnectedCore.multi.TYPES.map(t=>[t+'Reduction',ConnectedCore.multi.NAMES[t]+'减抗']))},pctLabels=ConnectedCore.multi.FIELDS.filter(([k])=>ConnectedCore.multi.legacy.PERCENT_FIELDS.has(k)).map(([,label])=>label);
  return diffRaw(normalize(a),normalize(b)).map(s=>{for(const[k,v]of Object.entries(labels))s=s.replace(k,v);const split=s.indexOf('：'),title=s.slice(0,split),parts=s.slice(split+1).split(' → ');if(parts.length===2&&parts.every(x=>Number.isFinite(num(x)))&&!/价格|加价|等级|启用/.test(title)&&(pctLabels.some(label=>title.includes(label))||title.includes('减抗')))s=title+'：'+parts.map(x=>f(num(x)*100)+'%').join(' → ');return s.replace('：false → true','：关闭 → 启用').replace('：true → false','：启用 → 关闭');});
