 by('cgExample').onclick=()=>install(ConnectedV2.example());by('cgCreate').onclick=()=>{game=null;baseGame=null;baseRuns=[];candidateRuns=[];drawForm(true);show('data');notice('');};by('cgDataTab').onclick=()=>{if(!formReady)drawForm(!game);show('data');};by('cgRunTab').onclick=()=>{if(!game){show('empty');return;}if(dirty){notice('先保存游戏数据，再运行模拟。',true);show('data');return;}show('simulation');runSummary();};by('cgResultsTab').onclick=()=>{show('results');if(baseRuns.length)renderResults();};by('cgEditData').onclick=by('cgChangeMyData').onclick=()=>{if(!formReady)drawForm(false);show('data');};by('cgForm').onsubmit=e=>{e.preventDefault();saveForm();};by('cgDataRun').onclick=()=>{if(saveForm())simulate(!!baseRuns.length);};by('cgDiscard').onclick=()=>{if(!game){show('empty');return;}drawForm(false);dirty=false;show('simulation');runSummary();notice('未保存修改已撤回。');};by('cgForm').oninput=e=>{dirty=true;e.target.removeAttribute('aria-invalid');by('cgGoalFields').hidden=by('cgGoalMode').value!=='set';};by('cgGoalMode').onchange=()=>{by('cgGoalFields').hidden=by('cgGoalMode').value!=='set';dirty=true;};by('cgRun').onclick=()=>simulate(false);by('cgCompare').onclick=()=>simulate(true);by('cgStop').onclick=()=>{if(worker){const reject=worker._reject;worker.terminate();worker=null;reject(Error('已停止'));}notice('已停止，已完成的样本仍保留。');};by('cgRunSelect').onchange=selectRun;by('cgLongest').onclick=()=>showDiagnosis(selectedRun.longestGap.stage);by('cgFirstFailure').onclick=()=>{if(selectedRun.firstBlock)showDiagnosis(selectedRun.firstBlock.stage);};by('cgOpenBattle').onclick=openBattle;by('cgCloseBattle').onclick=()=>{by('cgBattle').hidden=true;by('cgOpenBattle').focus();};by('cgBattleStep').onchange=renderMoment;by('cgBattlePrev').onclick=()=>{by('cgBattleStep').value=Math.max(0,Number(by('cgBattleStep').value)-1);renderMoment();};by('cgBattleNext').onclick=()=>{by('cgBattleStep').value=Math.min(replay.executed.steps.length-1,Number(by('cgBattleStep').value)+1);renderMoment();};by('cgStageRows').onclick=e=>{const b=e.target.closest('[data-cg-stage]');if(b){showDiagnosis(Number(b.dataset.cgStage));by('cgBlockTitle').scrollIntoView({block:'start'});}};by('cgSuggestions').onclick=e=>{const b=e.target.closest('[data-cg-suggest]');if(b)suggestion(b.dataset.cgSuggest);};
 by('cgKeep').onclick=()=>{baseGame=copy(game);baseRuns=copy(candidateRuns);candidateRuns=[];renderResults();show('results');notice('修改后的方案已作为新的对照。旧对照仍在此前导出的结果里，本机保存需点保存。');};by('cgUndo').onclick=()=>{game=copy(baseGame);candidateRuns=[];formReady=false;renderResults();show('results');notice('已恢复修改前的游戏与结果。');};by('cgSave').onclick=()=>{try{if(dirty){notice('请先保存当前表单数据。',true);return;}localStorage.setItem(stateKey,JSON.stringify(project(false)));notice('这一份游戏和修改前对照已保存到这台电脑；过程可另外导出。');}catch(e){notice('保存未成功，请导出配置文件。',true);}};by('cgRestore').onclick=()=>{try{const raw=localStorage.getItem(stateKey);if(!raw)throw Error('这台电脑还没有一体化游戏存档');loadProject(JSON.parse(raw));}catch(e){notice(e.message,true);}};by('cgExportConfig').onclick=()=>download('我的游戏配置-v1.json',project(false));by('cgExportResults').onclick=()=>download('我的游戏完整结果-v1.json',project(true));by('cgImport').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>25*1024*1024)throw Error('文件超过25MB，请使用本工具导出的配置或结果');loadProject(JSON.parse(await file.text()));}catch(error){notice(error.message,true);}finally{e.target.value='';}};by('cgLegacy').onclick=()=>{by('connected').hidden=true;document.body.classList.remove('connected-active');by('cgReturnConnected').hidden=false;notice('');};by('cgReturnConnected').onclick=()=>{by('connected').hidden=false;document.body.classList.add('connected-active');by('cgReturnConnected').hidden=true;};
 function onlineChange(a,b){const total=c=>c.behavior.mode==='continuous'?'1440':ConnectedCore.multiply(c.behavior.sessionMinutes,String(c.behavior.visitHours.length)),before=total(a),after=total(b);if(a.behavior.mode===b.behavior.mode&&a.behavior.visitHours.length===b.behavior.visitHours.length&&before===after)return'';return before===after?'每天总在线时长相同，但需要更频繁打开。':'每天总在线时长从'+f(before)+'分钟变为'+f(after)+'分钟；进度变化也包含在线时长的影响。';}
 const momentForChart=renderMoment;renderMoment=function(){momentForChart();if(replay)ConnectedCharts.followStep(Number(by('cgBattleStep').value)||0);};by('cgBattleStep').onchange=()=>{stopPlayback();renderMoment();};
 by('cgExportBattleCSV').onclick=()=>{const types=ConnectedCore.multi.TYPES,rows=battleLog().map(x=>{const a=x.event==='regen'?null:replay.executed.steps[x.step].attacks.find(a=>a.side===(x.event==='player'?0:1));return {...x,critical:a?.critical??'',blocked:a?.blocked??'',...Object.fromEntries(types.map(t=>['actual_'+t,x.channels?.[t]?.actualHpLost??(t==='fire'?x.channels?.element?.actualHpLost:null)??'0']))};});csvDownload('实际战斗逐击记录.csv',['time','name','critical','blocked','actual','playerHp','enemyHp',...types.map(t=>'actual_'+t)],rows);};
