 by('cgImport').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>256*1024*1024)throw Error('结果文件超过256MB，请减少一次导出的试算数量');loadProject(JSON.parse(await file.text()));}catch(error){notice(error.message,true);}finally{e.target.value='';}};
 by('cgEmpty').insertAdjacentHTML('beforeend','<details><summary>看一个可手算的完整例子</summary><p>两关，物理加冰霜，敌人冰抗50%。先运行原方案，再到数据页开启冰霜升级，保存后比较整条路线。</p><button type="button" id="cgIceExample">载入两关冰霜例子</button></details>');by('cgIceExample').onclick=()=>{install(copy(CONNECTED_ICE_EXAMPLE));notice('先整体检查：原方案应5秒打完。然后在数据页开启冰霜升级，保存并比较，应花10金币缩短到4秒。');};
